#!/usr/bin/env bash
set -euo pipefail
JC_FL_E2E_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"
JC_FL_E2E_STATE_ROOT="${JC_FL_E2E_STATE_ROOT:-/tmp/joincare-fair-launch-local-e2e}"
JC_FL_E2E_MYSQL_IMAGE='mysql@sha256:c831a0f11348d402b43d77453e17d770be2eef356615a2823fe0f5a0d6c8b9af'
JC_FL_E2E_DOCKER_SOCKET='/var/run/docker.sock'; JC_FL_E2E_AUTHORITY_HELPER="$JC_FL_E2E_ROOT/scripts/tests/fair_launch_local_e2e_authority.py"; JC_FL_E2E_CLEANUP_HELPER="$JC_FL_E2E_ROOT/scripts/tests/fair_launch_local_e2e_test_cleanup.py"; JC_FL_E2E_RUN_LABEL='joincare.fair-launch.local-e2e-run'; JC_FL_E2E_COMPONENT_LABEL='joincare.fair-launch.local-e2e-component'
jc_fl_e2e_fail(){ echo "fair-launch-local-e2e: FAIL: $*" >&2; exit 1; }
jc_fl_e2e_reject_external(){ for key in JC_DEPLOY_RPC JC_DEPLOY_CHAIN_ID JC_DEPLOY_PRIVATE_KEY JC_MYSQL_ROOT_PASSWORD MYSQL_PWD FAIR_LAUNCH_DISPOSABLE_MYSQL_DSN DOCKER_HOST DOCKER_CONTEXT DOCKER_TLS_VERIFY DOCKER_CERT_PATH SSH_AUTH_SOCK REDISCLI_AUTH; do [ -z "${!key:-}" ] || jc_fl_e2e_fail "refusing external/production environment: $key"; done; }
jc_fl_e2e_require_run_id(){ [[ "$1" =~ ^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$ ]] || jc_fl_e2e_fail 'invalid run id'; }
jc_fl_e2e_run_dir(){ printf '%s/%s' "$JC_FL_E2E_STATE_ROOT" "$1"; }
jc_fl_e2e_choose_port(){ local low="$1" port; for _ in $(seq 1 1000); do port=$((low+(0x$(od -An -N2 -tx2 /dev/urandom|tr -d ' ')%1000))); ss -H -ltn "sport = :$port"|grep -q .||{ echo "$port";return;}; done; return 1; }
jc_fl_e2e_docker(){ local bound=20s injected="${JC_FL_E2E_TEST_DOCKER_QUERY_FAIL:-}"; case "${JC_FL_E2E_TEST_DOCKER_TIMEOUT:-}" in '') ;; 1s|2s|5s|10s|20s) bound="$JC_FL_E2E_TEST_DOCKER_TIMEOUT";; *) jc_fl_e2e_fail 'invalid bounded test Docker timeout';; esac; case "$injected" in ''|'ps -aq'|'network ls'|'ps -aq ambiguous'|'ps -aq empty'|'inspect --format timeout'|'inspect --format error') ;; *) jc_fl_e2e_fail 'invalid Docker query injection';; esac; if [ "$injected" = "$1 ${2:-}" ]; then case "$injected" in *' error') return 1;; *) return 124;; esac; fi; if [ "$1 ${2:-}" = 'inspect --format' ]; then case "$injected" in 'inspect --format timeout') return 124;; 'inspect --format error') return 1;; esac; fi; if [ "$injected" = 'ps -aq empty' ]&&[ "$1 ${2:-}" = 'ps -aq' ]; then return 0; fi; if [ "$injected" = 'ps -aq ambiguous' ]&&[ "$1 ${2:-}" = 'ps -aq' ]; then printf '%064d\n%064d\n' 1 2; return 0; fi; timeout --foreground --kill-after=5s "$bound" docker -H "unix://$JC_FL_E2E_DOCKER_SOCKET" "$@"; }
jc_fl_e2e_trusted_timeout(){ local system_path candidate owner mode; system_path="$(getconf PATH 2>/dev/null)"||return 1; candidate="$(PATH="$system_path" command -v timeout 2>/dev/null)"||return 1; candidate="$(readlink -f "$candidate" 2>/dev/null)"||return 1; [ -x "$candidate" ]||return 1; owner="$(stat -Lc '%u' "$candidate" 2>/dev/null)"||return 1; mode="$(stat -Lc '%a' "$candidate" 2>/dev/null)"||return 1; [ "$owner" = 0 ]||return 1; [ $((8#$mode & 0022)) = 0 ]||return 1; printf '%s\n' "$candidate"; }
jc_fl_e2e_timeout_parent_owned(){ local bound="$1" script="$2" timeout_bin="$3";shift 3;local parent="/proc/$PPID" exe index;local -a actual=() expected=("$timeout_bin" '--foreground' '--kill-after=5s' "$bound" 'bash' "$script" "$@");exe="$(readlink -f "$parent/exe" 2>/dev/null)"||return 1;[ "$exe" = "$timeout_bin" ]||return 1;mapfile -d '' -t actual<"$parent/cmdline"||return 1;[ "${#actual[@]}" = "${#expected[@]}" ]||return 1;for index in "${!expected[@]}";do [ "${actual[$index]}" = "${expected[$index]}" ]||return 1;done; }
jc_fl_e2e_self_bound(){ local phase="$1" bound="$2" script timeout_bin; shift 2; case "${JC_FL_E2E_TEST_PHASE_TIMEOUT:-}" in '') ;; 1s) bound=1s;; *) jc_fl_e2e_fail 'invalid bounded test phase timeout';; esac; script="$(readlink -f "$0" 2>/dev/null)"||jc_fl_e2e_fail 'cannot canonicalize lifecycle script';timeout_bin="$(jc_fl_e2e_trusted_timeout)"||jc_fl_e2e_fail 'trusted system timeout unavailable';if [ "${JC_FL_E2E_PHASE_ACTIVE:-}" = "$phase" ]&&jc_fl_e2e_timeout_parent_owned "$bound" "$script" "$timeout_bin" "$@"; then return 0; fi; unset JC_FL_E2E_PHASE_ACTIVE; export JC_FL_E2E_PHASE_ACTIVE="$phase"; exec "$timeout_bin" --foreground --kill-after=5s "$bound" bash "$script" "$@"; }
jc_fl_e2e_test_phase_hold(){ [ "${JC_FL_E2E_TEST_HOLD_AT:-}" != "phase_entry_$1" ]||{ echo "HOLD_PHASE_ENTRY_$1" >&2;while :;do sleep 1;done;}; }
jc_fl_e2e_proc_start(){ awk '{print $22}' "/proc/$1/stat" 2>/dev/null; }
jc_fl_e2e_proc_exe(){ readlink -f "/proc/$1/exe" 2>/dev/null; }
jc_fl_e2e_proc_exe_inode(){ stat -Lc '%d:%i' "/proc/$1/exe" 2>/dev/null; }
jc_fl_e2e_proc_cmdline(){ tr '\0' ' ' < "/proc/$1/cmdline" 2>/dev/null; }
jc_fl_e2e_image_id(){ jc_fl_e2e_docker image inspect --format '{{.Id}}' "$JC_FL_E2E_MYSQL_IMAGE" 2>/dev/null; }
jc_fl_e2e_phase_write(){ python3 "$JC_FL_E2E_AUTHORITY_HELPER" phase-write "$1"; }
jc_fl_e2e_phase_update(){ python3 "$JC_FL_E2E_AUTHORITY_HELPER" phase-update "$1/evidence/lifecycle-phase.json" "$2" "$3" "$4" >/dev/null; }
jc_fl_e2e_phase_verify(){ python3 "$JC_FL_E2E_AUTHORITY_HELPER" phase-verify "$1/evidence/lifecycle-phase.json"; }
jc_fl_e2e_phase_requires(){ local state;state="$(jc_fl_e2e_phase_verify "$1")"||return 1;shift;for expected in "$@";do printf '%s\n' "$state"|grep -Fxq "$expected"||return 1;done;}
jc_fl_e2e_state_root_prepare(){ local root="$JC_FL_E2E_STATE_ROOT" parent marker;[[ "$root" = /* ]]||return 1;[ ! -L "$root" ]||return 1;if [ ! -e "$root" ];then parent="$(dirname "$root")";[ -d "$parent" ]&&[ ! -L "$parent" ]&&[ "$(readlink -f "$parent")" = "$parent" ]||return 1;umask 077;mkdir "$root"||return 1;fi;[ -d "$root" ]&&[ ! -L "$root" ]&&[ "$(readlink -f "$root")" = "$root" ]&&[ "$(stat -Lc '%u:%a' "$root")" = "$(id -u):700" ]||return 1;marker="$root/.jc-fl-test-root.json";if [ -e "$marker" ]||[ -L "$marker" ];then python3 "$JC_FL_E2E_AUTHORITY_HELPER" root-verify "$root">/dev/null;else [ -z "$(find "$root" -mindepth 1 -maxdepth 1 -print -quit)" ]||return 1;python3 "$JC_FL_E2E_AUTHORITY_HELPER" root-write "$root" JC_FL_TEST_LOCAL_E2E_RUNTIME_V1;fi;}
jc_fl_e2e_redis_fingerprint_write(){ local pid="$1" file="$2" redis_exe;redis_exe="$(readlink -f "$(command -v redis-server)")"||return 1;python3 "$JC_FL_E2E_ROOT/scripts/fair-launch/local-e2e/redis-process-record.py" write "$pid" "$RUN_DIR" "$REDIS_CONFIG" "127.0.0.1:$REDIS_PORT" "$redis_exe" "$file"; }
jc_fl_e2e_redis_owned(){ python3 "$JC_FL_E2E_ROOT/scripts/fair-launch/local-e2e/redis-process-record.py" verify "$1" >/dev/null 2>&1; }
jc_fl_e2e_redis_identity(){ python3 "$JC_FL_E2E_ROOT/scripts/fair-launch/local-e2e/redis-process-record.py" verify "$1" 2>/dev/null; }
jc_fl_e2e_redis_absent(){ python3 "$JC_FL_E2E_ROOT/scripts/fair-launch/local-e2e/redis-process-record.py" absence "$1" >/dev/null 2>&1; }
jc_fl_e2e_reservation_released_owned(){ local out; [ -f "$RUN_DIR/mysql-transport/reservation-released.json" ]&&[ "$(stat -Lc '%a' "$RUN_DIR/mysql-transport/reservation-released.json")" = 600 ]||return 1; out="$(python3 "$JC_FL_E2E_ROOT/scripts/fair-launch/local-e2e/mysql-port-reservation.py" verify-release "$RUN_DIR/mysql-transport/reservation-released.json" 2>/dev/null)"||return 1; [ "$(printf '%s\n' "$out"|sed -n 's/^ENDPOINT=//p')" = "$MYSQL_ENDPOINT" ]&&[ "$(printf '%s\n' "$out"|sed -n 's/^RESERVATIONDIGEST=//p')" = "$MYSQL_RESERVATION_DIGEST" ]; }
jc_fl_e2e_transport_digest(){ printf 'JC_FL_MYSQL_TRANSPORT_V1|%s|%s|%s|%s|host|network-not-used|127.0.0.1:%s|%s/tcp|%s|%s|%s|%s' "$RUN_ID" "$MYSQL_CONTAINER_ID" "$MYSQL_IMAGE_REF" "$MYSQL_IMAGE_ID" "$MYSQL_PORT" "$MYSQL_PORT" "$DB_NAME" "$MYSQL_SERVER_UUID" "$MYSQL_VERSION" "$MYSQL_RESERVATION_DIGEST"|sha256sum|awk '{print $1}'; }
jc_fl_e2e_mysql_listener_exact(){ local rows; [[ "$MYSQL_PORT" =~ ^[0-9]+$ ]]&&[ "$MYSQL_PORT" -ge 1024 ]&&[ "$MYSQL_PORT" -le 65535 ]||return 1; rows="$(ss -H -ltn "sport = :$MYSQL_PORT" 2>/dev/null)"; [ -n "$rows" ]&&printf '%s\n' "$rows"|awk -v endpoint="127.0.0.1:$MYSQL_PORT" 'NF&&$4!=endpoint{exit 1} END{if(NR==0)exit 1}'; }
jc_fl_e2e_mysql_container_static_owned(){ local id="$1" image_ref="$2" image_id="$3" port="$4" run="$5" name="$6" run_dir="$7" tmp container_json image_json rc; [ "$(jc_fl_e2e_image_id)" = "$image_id" ]&&[ "$image_ref" = "$JC_FL_E2E_MYSQL_IMAGE" ]||return 1; tmp="$(mktemp -d)"||return 1; chmod 700 "$tmp"; container_json="$tmp/container.json"; image_json="$tmp/image.json"; jc_fl_e2e_docker inspect "$id">"$container_json" 2>/dev/null&&jc_fl_e2e_docker image inspect "$image_ref">"$image_json" 2>/dev/null&&python3 "$JC_FL_E2E_ROOT/scripts/fair-launch/local-e2e/mysql-container-spec.py" "$container_json" "$image_json" "$id" "$image_ref" "$image_id" "$port" "$run" "$name" "$run_dir" "$JC_FL_E2E_ROOT" >/dev/null 2>&1; rc=$?; rm -rf "$tmp"; return "$rc"; }
jc_fl_e2e_mysql_transport_owned(){ local pid started server digest; [ "$MYSQL_ENDPOINT" = "127.0.0.1:$MYSQL_PORT" ]&&[ "$MYSQL_NAME" = "jc-fl-e2e-mysql-$RUN_HEX" ]&&[ "$MYSQL_NETWORK_MODE|$MYSQL_NETWORK_ID|$MYSQL_NETWORK_NAME" = 'host|network-not-used|network-not-used' ]&&[ "$DB_NAME" = "jc_fl_e2e_$RUN_HEX" ]||return 1; jc_fl_e2e_mysql_container_static_owned "$MYSQL_CONTAINER_ID" "$MYSQL_IMAGE_REF" "$MYSQL_IMAGE_ID" "$MYSQL_PORT" "$RUN_ID" "$MYSQL_NAME" "$RUN_DIR"||return 1; pid="$(jc_fl_e2e_docker inspect --format '{{.State.Pid}}' "$MYSQL_CONTAINER_ID")"; started="$(jc_fl_e2e_docker inspect --format '{{.State.StartedAt}}' "$MYSQL_CONTAINER_ID")"; [ "$pid" = "$MYSQL_CONTAINER_PID" ]&&[ "$started" = "$MYSQL_CONTAINER_STARTED_AT" ]&&[ "$(jc_fl_e2e_docker inspect --format '{{.State.Running}}' "$MYSQL_CONTAINER_ID")" = true ]||return 1; jc_fl_e2e_reservation_released_owned&&jc_fl_e2e_mysql_listener_exact||return 1; server="$(jc_fl_e2e_docker exec "$MYSQL_CONTAINER_ID" mysql --defaults-extra-file=/tmp/root.cnf --port="$MYSQL_PORT" --batch --raw --skip-column-names -e 'SELECT CONCAT(LOWER(@@server_uuid),"|",VERSION());' 2>/dev/null)"||return 1; [ "$server" = "$MYSQL_SERVER_UUID|$MYSQL_VERSION" ]||return 1; digest="$(jc_fl_e2e_transport_digest)"; [ "$digest" = "$MYSQL_TRANSPORT_DIGEST" ]; }
jc_fl_e2e_evidence_digest(){ sha256sum "$1"|awk '{print $1}'; }
jc_fl_e2e_evidence_target(){ local path="$1" parent="$(dirname "$1")";[ -d "$parent" ]&&[ ! -L "$parent" ]&&[ "$(readlink -f "$parent")" = "$parent" ]&&[ "$(stat -Lc '%u:%a' "$parent")" = "$(id -u):700" ]||return 1;if [ -e "$path" ]||[ -L "$path" ];then [ -f "$path" ]&&[ ! -L "$path" ]&&[ "$(stat -Lc '%u:%a:%h' "$path")" = "$(id -u):600:1" ]||return 1;fi;}
jc_fl_e2e_mysql_profiles_ready(){ local role p; [ "${MYSQL_SCHEMA_READY:-0}" = 1 ]&&[ -f "$RUN_DIR/evidence/schema-readiness.json" ]||return 1; for role in runtime admin job ingest; do p="$RUN_DIR/credentials/mysql-$role.cnf"; [ -f "$p" ]||return 1; [ "$(bash "$JC_FL_E2E_ROOT/scripts/fair-launch/local-e2e/mysql-secret-helper.sh" verify-profile "$p" "$MYSQL_PORT" "$MYSQL_SERVER_UUID" "$MYSQL_VERSION" "$DB_NAME" "local_$role" 2>/dev/null)" = verified ]||return 1; done; python3 "$JC_FL_E2E_ROOT/scripts/fair-launch/local-e2e/schema-readiness.py" verify "$RUN_DIR" "$RUN_ID" "$MYSQL_TRANSPORT_DIGEST" "$MYSQL_IMAGE_ID" "$BASELINE_DIGEST" "$MIGRATION_MANIFEST_DIGEST" "$SCHEMA_DIGEST" "$GRANT_POLICY_DIGEST" "$OWNER_LABEL_DIGEST" >/dev/null 2>&1; }
jc_fl_e2e_container_source_publish(){ local id="$1" component="$2" record="$3" inspect="${3}.inspect.new";[[ "$id" =~ ^[0-9a-f]{64}$ ]]||return 1;[ "$component" = mysql ]||[ "$component" = foreign ]||return 1;python3 "$JC_FL_E2E_AUTHORITY_HELPER" root-verify "$(dirname "$RUN_DIR")">/dev/null||return 1;jc_fl_e2e_phase_requires "$RUN_DIR" DOCKER_ATTEMPTED=true||return 1;[ ! -e "$record" ]&&[ ! -L "$record" ]&&[ ! -e "$inspect" ]&&[ ! -L "$inspect" ]||return 1;jc_fl_e2e_evidence_target "$inspect"||return 1;umask 077;jc_fl_e2e_docker inspect "$id">"$inspect" 2>&1||return 1;chmod 600 "$inspect";python3 "$JC_FL_E2E_CLEANUP_HELPER" container-record "$inspect" "$RUN_ID" "$component" "$RUN_DIR" "$record"||return 1;[ "$(python3 "$JC_FL_E2E_CLEANUP_HELPER" container-static-verify "$record")" = "$id" ];}
jc_fl_e2e_docker_remove_exact(){
 local id="$1" evidence="$2" source="${2}.source.json" removal="${2}.source.json.removal.json" absence="${2}.absence.json" inspect1="${2}.source.json.inspect.1" inspect2="${2}.source.json.inspect.2" query="${2}.source.json.post-rm-query" query_raw="${2}.source.json.post-rm-query.raw" out="${2}.rm-output" stage='' rc
 [[ "$id" =~ ^[0-9a-f]{64}$ ]]||return 1
 [ -n "${RUN_DIR:-}" ]&&[ -n "${RUN_ID:-}" ]||return 1
 python3 "$JC_FL_E2E_AUTHORITY_HELPER" root-verify "$(dirname "$RUN_DIR")">/dev/null||return 1
 jc_fl_e2e_phase_requires "$RUN_DIR" DOCKER_ATTEMPTED=true||return 1
 [ -d "$RUN_DIR" ]&&[ ! -L "$RUN_DIR" ]&&[ "$(readlink -f "$RUN_DIR")" = "$RUN_DIR" ]&&[ "$(stat -Lc '%u:%a' "$RUN_DIR")" = "$(id -u):700" ]||return 1
 [ -d "$(dirname "$evidence")" ]&&[ ! -L "$(dirname "$evidence")" ]&&[ "$(readlink -f "$(dirname "$evidence")")" = "$(dirname "$evidence")" ]&&[ "$(stat -Lc '%u:%a' "$(dirname "$evidence")")" = "$(id -u):700" ]||return 1
 umask 077
 if [ -e "$absence" ]||[ -L "$absence" ];then [ -e "$source" ]||[ -L "$source" ]||return 1;[ "$(python3 "$JC_FL_E2E_CLEANUP_HELPER" absence-covers "$absence" "$source")" = "$id" ];return
 fi
 if [ -e "$source" ]||[ -L "$source" ];then
  [ "$(python3 "$JC_FL_E2E_CLEANUP_HELPER" container-static-verify "$source")" = "$id" ]||return 1
  if [ -e "$removal" ]||[ -L "$removal" ];then stage="$(python3 "$JC_FL_E2E_CLEANUP_HELPER" removal-stage "$removal" "$source")"||return 1;fi
 else
  [ ! -e "$source" ]&&[ ! -L "$source" ]&&[ ! -e "$evidence" ]&&[ ! -L "$evidence" ]&&[ ! -e "$removal" ]&&[ ! -L "$removal" ]||return 1
  [ ! -e "${source}.inspect.new" ]&&[ ! -L "${source}.inspect.new" ]||return 1;jc_fl_e2e_docker inspect "$id">"${source}.inspect.new" 2>&1||return 1;chmod 600 "${source}.inspect.new"
  python3 "$JC_FL_E2E_CLEANUP_HELPER" container-record "${source}.inspect.new" "$RUN_ID" mysql "$RUN_DIR" "$source"||return 1
 fi
 [ -n "$stage" ]||{ [ ! -e "$query" ]&&[ ! -L "$query" ]||return 1; }
 if [ "$stage" = RM_SUCCEEDED_QUERY_PENDING ];then
  if [ -e "$query" ]||[ -L "$query" ];then python3 "$JC_FL_E2E_CLEANUP_HELPER" query-verify "$query" "$source">/dev/null||return 1;python3 "$JC_FL_E2E_CLEANUP_HELPER" absence-write "$source" "$removal" "$query" "$absence"||return 1;return 0;fi
  jc_fl_e2e_evidence_target "$query_raw"||return 1;if jc_fl_e2e_docker inspect --format '{{.Id}}' "$id">"$query_raw" 2>&1;then rc=0;else rc=$?;fi;chmod 600 "$query_raw";[ "$rc" != 0 ]||return 1
  python3 "$JC_FL_E2E_CLEANUP_HELPER" query-write "$source" "$query_raw" "$rc" "$query"||return 1
  python3 "$JC_FL_E2E_CLEANUP_HELPER" absence-write "$source" "$removal" "$query" "$absence"||return 1;return 0
 fi
 if [ "$stage" = AUTHORIZED_BEFORE_RM ];then
  if [ -e "$query" ]||[ -L "$query" ];then python3 "$JC_FL_E2E_CLEANUP_HELPER" query-verify "$query" "$source">/dev/null||return 1;python3 "$JC_FL_E2E_CLEANUP_HELPER" absence-promote "$source" "$removal" "$query" "$absence"||return 1;return 0;fi
  jc_fl_e2e_evidence_target "$query_raw"||return 1;if jc_fl_e2e_docker inspect --format '{{.Id}}' "$id">"$query_raw" 2>&1;then rc=0;else rc=$?;fi;chmod 600 "$query_raw"
  if [ "$rc" != 0 ];then python3 "$JC_FL_E2E_CLEANUP_HELPER" query-write "$source" "$query_raw" "$rc" "$query"||return 1;python3 "$JC_FL_E2E_CLEANUP_HELPER" absence-promote "$source" "$removal" "$query" "$absence"||return 1;return 0;fi
 fi
 [ -z "$stage" ]||[ "$stage" = AUTHORIZED_BEFORE_RM ]||return 1
 jc_fl_e2e_evidence_target "$inspect1"||return 1;jc_fl_e2e_docker inspect "$id">"$inspect1" 2>&1||return 1;chmod 600 "$inspect1";python3 "$JC_FL_E2E_CLEANUP_HELPER" container-verify "$source" "$inspect1">/dev/null||return 1
 jc_fl_e2e_evidence_target "$inspect2"||return 1;jc_fl_e2e_docker inspect "$id">"$inspect2" 2>&1||return 1;chmod 600 "$inspect2";python3 "$JC_FL_E2E_CLEANUP_HELPER" container-verify "$source" "$inspect2">/dev/null||return 1
 [ -n "$stage" ]||python3 "$JC_FL_E2E_CLEANUP_HELPER" removal-write "$source" "$removal">/dev/null||return 1
 jc_fl_e2e_evidence_target "$out"||return 1;if [ "${JC_FL_E2E_TEST_LIFECYCLE_DOCKER_RM_FAIL:-0}" = 1 ];then printf '%s\n' injected-lifecycle-rm-failure >"$out";chmod 600 "$out";return 1;fi
 python3 "$JC_FL_E2E_AUTHORITY_HELPER" root-verify "$(dirname "$RUN_DIR")">/dev/null||return 1;jc_fl_e2e_phase_requires "$RUN_DIR" DOCKER_ATTEMPTED=true||return 1;python3 "$JC_FL_E2E_CLEANUP_HELPER" removal-verify "$removal" "$source" AUTHORIZED_BEFORE_RM>/dev/null||return 1
 if jc_fl_e2e_docker rm -f "$id">"$out" 2>&1;then rc=0;else rc=$?;fi;chmod 600 "$out";[ "$rc" = 0 ]||return 1
 python3 "$JC_FL_E2E_CLEANUP_HELPER" removal-update "$removal" "$source" AUTHORIZED_BEFORE_RM RM_SUCCEEDED_QUERY_PENDING>/dev/null||return 1
 jc_fl_e2e_evidence_target "$query_raw"||return 1;if [ "${JC_FL_E2E_TEST_LIFECYCLE_POST_RM_QUERY_FAIL:-0}" = 1 ];then printf '%s\n' injected-lifecycle-post-rm-query-failure >"$query_raw";chmod 600 "$query_raw";return 1;fi
 if jc_fl_e2e_docker inspect --format '{{.Id}}' "$id">"$query_raw" 2>&1;then rc=0;else rc=$?;fi;chmod 600 "$query_raw";[ "$rc" != 0 ]||return 1
 python3 "$JC_FL_E2E_CLEANUP_HELPER" query-write "$source" "$query_raw" "$rc" "$query"||return 1
 python3 "$JC_FL_E2E_CLEANUP_HELPER" absence-write "$source" "$removal" "$query" "$absence"||return 1
}
jc_fl_e2e_load_state(){ local run_id="$1" dir key value verified='';jc_fl_e2e_state_root_prepare||jc_fl_e2e_fail 'state root authority invalid';jc_fl_e2e_require_run_id "$run_id";dir="$(jc_fl_e2e_run_dir "$run_id")";python3 "$JC_FL_E2E_AUTHORITY_HELPER" root-verify "$JC_FL_E2E_STATE_ROOT">/dev/null||jc_fl_e2e_fail 'state root authority invalid';jc_fl_e2e_phase_requires "$dir" REDIS_ATTEMPTED=true DOCKER_ATTEMPTED=true STAGE=transport-published||jc_fl_e2e_fail 'run lifecycle phase invalid';while IFS= read -r -d '' key&&IFS= read -r -d '' value;do if [ "$key" = __JC_FL_STATE_VERIFIED__ ];then verified="$value";else printf -v "$key" '%s' "$value";fi;done< <(python3 "$JC_FL_E2E_AUTHORITY_HELPER" state-read "$dir/state.env" "$run_id" "$dir");[ "$verified" = yes ]&&[ "$RUN_ID" = "$run_id" ]&&[ "$RUN_DIR" = "$dir" ]||jc_fl_e2e_fail 'run state authority invalid';python3 "$JC_FL_E2E_AUTHORITY_HELPER" root-verify "$JC_FL_E2E_STATE_ROOT">/dev/null&&jc_fl_e2e_phase_requires "$dir" REDIS_ATTEMPTED=true DOCKER_ATTEMPTED=true STAGE=transport-published||jc_fl_e2e_fail 'run authority changed during state load';REDIS_CONFIG="$RUN_DIR/redis/redis.conf";REDIS_FINGERPRINT="$RUN_DIR/redis/process.json";}
